DECLARE 
	@Prod int, 
	@Qtd_at int, 
	@Tt_Ent int, 
	@Tt_Sai int, 
	@DatIni datetime,
	@datf datetime,
	@dat1 datetime = '20230401',
	@dat2 datetime = '20230930',
	@Estab int = 1

Declare CodProdut CURSOR FOR
		SELECT COD_PRODUT 
		FROM PRSLD
		WHERE 
			COD_ESTABE = 1 AND 
			Dat_Movime >= '20230401' AND
			Dat_Movime <= '20230930' AND
			EXISTS (
			SELECT DISTINCT COD_PRODUT
			FROM PREAN
			WHERE COD_EAN IN (
			'7891317000066'  ,'7891317000110' ,'7891317000127' ,'7891317000509' ,'7891317000530' ,'7891317001056' ,'7891317001063' ,'7891317001070' ,'7891317001414' ,'7891317001421' ,'7891317001438' ,'7891317001476' ,'7891317001483' ,'7891317001513'
			,'7891317001568' ,'7891317001636' ,'7891317001872' ,'7891317001926' ,'7891317002022' ,'7891317002190' ,'7891317002442' ,'7891317002459' ,'7891317002497' ,'7891317002503' ,'7891317002572' ,'7891317002596' ,'7891317002602' ,'7891317002688'
			,'7891317002695' ,'7891317002954' ,'7891317003050' ,'7891317003487' ,'7891317003494' ,'7891317003630' ,'7891317003647' ,'7891317004286' ,'7891317004293' ,'7891317004316' ,'7891317004323' ,'7891317004330' ,'7891317004347' ,'7891317004354'
			,'7891317004361' ,'7891317004606' ,'7891317005054' ,'7891317005252' ,'7891317005269' ,'7891317005757' ,'7891317005764' ,'7891317005900' ,'7891317005917' ,'7891317007287' ,'7891317007294' ,'7891317007607' ,'7891317007829' ,'7891317007836'
			,'7891317007898' ,'7891317008406' ,'7891317008932' ,'7891317009052' ,'7891317009083' ,'7891317009106' ,'7891317009113' ,'7891317009168' ,'7891317009434' ,'7891317009441' ,'7891317009915' ,'7891317009922' ,'7891317010164' ,'7891317010171'
			,'7891317010188' ,'7891317010195' ,'7891317010263' ,'7891317010270' ,'7891317010355' ,'7891317010362' ,'7891317010744' ,'7891317010829' ,'7891317010911' ,'7891317011154' ,'7891317011420' ,'7891317013547' ,'7891317013646' ,'7891317013653'
			,'7891317016326' ,'7891317016333' ,'7891317016371' ,'7891317016388' ,'7891317016395' ,'7891317016852' ,'7891317016869' ,'7891317016920' ,'7891317017026' ,'7891317017033' ,'7891317017040' ,'7891317017422' ,'7891317017651' ,'7891317017668'
			,'7891317017675' ,'7891317018542' ,'7891317018849' ,'7891317020002' ,'7891317021931' ,'7891317021948' ,'7891317021962' ,'7891317025083' ,'7891317025786' ,'7891317101961' ,'7891317101985' ,'7891317102012' ,'7891317120849' ,'7891317121198'
			,'7891317121235' ,'7891317123956' ,'7891317123994' ,'7891317124038' ,'7891317124472' ,'7891317124489' ,'7891317127404' ,'7891317127428' ,'7891317127725' ,'7891317127800' ,'7891317133634' ,'7891317133689' ,'7891317133733' ,'7891317134303'
			,'7891317137359' ,'7891317139384' ,'7891317139469' ,'7891317140458' ,'7891317140779' ,'7891317140854' ,'7891317141967' ,'7891317141974' ,'7891317143046' ,'7891317143053' ,'7891317154332' ,'7891317154721' ,'7891317155056' ,'7891317155131'
			,'7891317155216' ,'7891317160920' ,'7891317172657' ,'7891317172664' ,'7891317180539' ,'7891317180553' ,'7891317189631' ,'7891317189648' ,'7891317191733' ,'7891317191740' ,'7891317191757' ,'7891317191771' ,'7891317191788' ,'7891317191795'
			,'7891317192822' ,'7891317193164' ,'7891317414139' ,'7891317414221' ,'7891317420338' ,'7891317421823' ,'7891317421854' ,'7891317421861' ,'7891317421991' ,'7891317422028' ,'7891317422042' ,'7891317424565' ,'7891317427542' ,'7891317430146'
			,'7891317430368' ,'7891317431334' ,'7891317431358' ,'7891317433642' ,'7891317433673' ,'7891317434328' ,'7891317434335' ,'7891317434342' ,'7891317435936' ,'7891317435943' ,'7891317444747' ,'7891317444921' ,'7891317445287' ,'7891317445294'
			,'7891317445300' ,'7891317446031' ,'7891317446659' ,'7891317446772' ,'7891317446819' ,'7891317446963' ,'7891317448653' ,'7891317448677' ,'7891317448936' ,'7891317448943' ,'7891317450359' ,'7891317451035' ,'7891317452230' ,'7891317452254'
			,'7891317452964' ,'7891317452971' ,'7891317452995' ,'7891317453008' ,'7891317454371' ,'7891317456559' ,'7891317457266' ,'7891317458850' ,'7891317458867' ,'7891317461089' ,'7891317462031' ,'7891317463076' ,'7891317464523' ,'7891317465643'
			,'7891317469283' ,'7891317472009' ,'7891317472122' ,'7891317472139' ,'7891317473648' ,'7891317473679' ,'7891317473709' ,'7891317476465' ,'7891317476526' ,'7891317477271' ,'7891317477301' ,'7891317477592' ,'7891317477608' ,'7891317478766'
			,'7891317478810' ,'7891317481629' ,'7891317481636' ,'7891317482541' ,'7891317484262' ,'7891317484330' ,'7891317484408' ,'7891317487386' ,'7891317488352' ,'7891317488390' ,'7891317488833' ,'7891317489328' ,'7891317489366' ,'7891317489403'
			,'7891317490003' ,'7891317496388' ,'7891317496753' ,'7898146826768'
			))

OPEN CodProdut

FETCH NEXT FROM CodProdut INTO @Prod

WHILE @@FETCH_STATUS = 0

	BEGIN
		DECLARE QTD_ANT CURSOR FOR 
			select top 1 
					Qtd_SldAtu, 
					Dat_Movime 
				from PRSLD
				where 
					Cod_Estabe = @Estab AND
					Cod_Produt =  @Prod AND
					Qtd_SldAtu > 0 AND
					Dat_Movime <  @dat1
				order by Dat_Movime desc
		OPEN QTD_ANT
		FETCH NEXT FROM QTD_ANT INTO @Qtd_at, @DatIni 
		WHILE @@FETCH_STATUS = 0
		BEGIN
	
			DECLARE Datas CURSOR FOR
						SELECT 
							Max(Dat_Movime) as Datas, 
							sum(Qtd_EntCom + Qtd_EntDev + Qtd_EntOut + Qtd_EntTrf) as Ent,
							sum(Qtd_SaiVen + Qtd_SaiDev + Qtd_SaiOut + Qtd_SaiTrf) as Sai
						FROM PRSLD
						WHERE 
							Cod_Estabe = @Estab AND
							Dat_Movime >= @dat1 AND
							Dat_Movime <= @dat2 AND
							Cod_Produt = @Prod
						
			OPEN Datas
			FETCH NEXT FROM Datas INTO @datf, @Tt_Ent, @Tt_Sai

			WHILE @@FETCH_STATUS = 0
				BEGIN

					SELECT 
						@Prod as Produto, 
						@DatIni as Dat_Estoq_Ant, 
						@Qtd_at as Estoq_Ant, 
						@datf as Ult_Movimentacao, 
						@Tt_Ent as Total_Entrada, 
						Total_Saida = 
								Case 
									when @Tt_Sai < 0 then (@Tt_Sai * -1) 
									when @Tt_Sai = 0 then @Tt_Sai
									when @Tt_Sai > 0 then (@Tt_Sai * -1) 
								end,
						Estoque_Final = ((@Tt_Ent + @Qtd_at) - @Tt_Sai)
				
				FETCH NEXT FROM Datas INTO @datf, @Tt_Ent, @Tt_Sai
				
				END
		CLOSE Datas
		DEALLOCATE Datas

	FETCH NEXT FROM QTD_ANT INTO @Qtd_at, @DatIni 
	END
	CLOSE QTD_ANT
	DEALLOCATE QTD_ANT
FETCH NEXT FROM CodProdut INTO @Prod
END
CLOSE CodProdut
DEALLOCATE CodProdut